import csv
from collections import defaultdict
ids = {
 'Chiller02':'6041ce4e-9251-5a23-9103-a13dcc247d28',
 'HWPump02':'af4b8334-3dca-548d-b215-2cb64a0aa2c0',
 'SupplyFan_AHU03':'d8a9536c-e875-5be1-90c1-dcfdcb016492',
}
name_by_id={v:k for k,v in ids.items()}
sums=defaultdict(float)
counts=defaultdict(int)
with open(VALUES_CSV) as f:
    r=csv.reader(f); next(r)
    for tsid,ts,val in r:
        if tsid in name_by_id and ts.startswith('2018-04-02'):
            sums[name_by_id[tsid]]+=float(val)
            counts[tsid]+=1
for name in ids:
    print(name, sums[name],'Wh =',round(sums[name]/1000,3),'kWh', 'h=',counts[ids[name]])
